<script setup lang="ts">
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue';
import {ElMessage} from 'element-plus';
import {usePlatform} from '../stores/platform';
import {filterRows} from '../domain';
import type {Capture,Field} from '../domain';
import QueryForm from '../components/QueryForm.vue';
import DataTable from '../components/DataTable.vue';
import {download} from '../utils/files';import {apiMode,request,downloadFileBinary,isRequestCanceled} from '../api/client';
import {uploadControlled} from '../api/resources';
import {feature,timeRange,captureView} from '../api/gateway';
import {awaitTask} from '../api/tasks';
const p=usePlatform();const candidateLimit=ref<number>(),faceBusy=ref(false),faceError=ref(''),imageAssetId=ref(''),images=ref<Record<string,string>>({});let alive=true;let controller=new AbortController();
async function startFaceSearch(assetId:string){feature('FACE_SEARCH');if(!Number.isInteger(candidateLimit.value)||Number(candidateLimit.value)<1)throw new Error('请填写已确认的候选数量上限');controller.abort();controller=new AbortController();faceBusy.value=true;faceError.value='';const timeout=setTimeout(()=>controller.abort(),120000);try{const siteId=p.db.sites.find(s=>s.name===p.f.site)?.id;const task=(await request('createFaceSearchTask',{body:{imageAssetId:assetId,timeRange:timeRange(p.f),candidateLimit:candidateLimit.value!,minSimilarity:p.similarity/100,...siteId?{siteIds:[siteId]}:{}},signal:controller.signal})).data;await awaitTask(task.taskId,{signal:controller.signal,intervalSeconds:p.remote.config?.taskPollIntervalSeconds||1});const result=(await request('listFaceSearchResults',{path:{taskId:task.taskId},query:{pageSize:100},signal:controller.signal})).data;p.db.captures=result.items.map(item=>({...captureView(item.capture,p.db),score:item.similarity*100}));faceTask.value=task.taskId;faceCursor.value=result.nextCursor;imageAssetId.value=assetId;}finally{clearTimeout(timeout);faceBusy.value=false;}}
const faceTask=ref(''),faceCursor=ref<string|null>(null);
async function moreFaces(){try{if(!faceTask.value||!faceCursor.value)return;const result=(await request('listFaceSearchResults',{path:{taskId:faceTask.value},query:{pageSize:100,cursor:faceCursor.value},signal:controller.signal})).data;p.db.captures.push(...result.items.map(item=>({...captureView(item.capture,p.db),score:item.similarity*100})));faceCursor.value=result.nextCursor;}catch(e){faceError.value=e instanceof Error?e.message:String(e);}}
async function guardedFace(run:()=>Promise<void>){faceError.value='';try{await run();}catch(e){if(!isRequestCanceled(e))faceError.value=e instanceof Error?e.message:String(e);}}
watch(()=>p.db.captures.map(r=>r.id),async ids=>{if(apiMode!=='http'||p.active!=='人像检索')return;for(const id of ids){const record=p.remote.captures[id];if(record?.dataType!=='FACE'||!record.face.imageAssetId||images.value[id])continue;try{const blob=await downloadFileBinary(record.face.imageAssetId);if(alive&&blob.type.startsWith('image/'))images.value[id]=URL.createObjectURL(blob);}catch{/* 图像无权限或过期时保留占位，保存操作仍显示具体错误。 */}}},{immediate:true});
onBeforeUnmount(()=>{alive=false;controller.abort();Object.values(images.value).forEach(url=>URL.revokeObjectURL(url));});
const type=computed(()=>({'围栏检索':'电围','车牌检索':'车牌','MAC检索':'MAC','人像检索':'人像'} as Record<string,string>)[p.active]||'电围');
const face=computed(()=>type.value==='人像');
const fields=computed<Field[]>(()=>[{key:'site',label:'场所',options:['全部',...p.visibleSites.map(s=>s.name)]},{key:'start',label:'采集开始',type:'datetime-local'},{key:'end',label:'采集结束',type:'datetime-local'},...face.value?[]:[{key:'target',label:type.value==='电围'?'IMSI':type.value==='车牌'?'车牌号':'MAC地址'},...type.value==='电围'?[{key:'imei',label:'IMEI'}]:[]]]);
const rows=computed(()=>p.filterRows(p.captureRows(type.value),p.f,{site:r=>r.site,start:r=>r.time,end:r=>r.time,target:r=>r.target,imei:r=>r.imei}).map(r=>({...r,score:apiMode==='mock'&&face.value&&p.faceSource?[100,92,78,61,35,12][(Number(r.person.replace(/\D/g,''))-p.faceReference+6)%6]||0:r.score})).filter(r=>!face.value||!p.faceSource||r.score>p.similarity));
const columns=[{key:'time',label:'采集时间'},{key:'type',label:'类型'},{key:'target',label:'目标标识'},{key:'imei',label:'IMEI'},{key:'site',label:'场所'},{key:'device',label:'设备',link:true}];
const context=ref<{x:number;y:number;row:Capture}|null>(null);
const closeOnEscape=(event:KeyboardEvent)=>{if(event.key==='Escape')context.value=null;};
onMounted(()=>document.addEventListener('keydown',closeOnEscape));onBeforeUnmount(()=>document.removeEventListener('keydown',closeOnEscape));
const contextNames=computed(()=>face.value?['轨迹','伴随','布控','位置追踪']:['复制','统计','轨迹','伴随','检索','布控','位置追踪','区域统计','添加数据集']);
function disabled(name:string){const selected=p.chosen as unknown as Capture[];if(['区域统计','添加数据集'].includes(name))return selected.length>0;return face.value?name==='伴随'&&new Set((selected.length?selected:[context.value?.row]).map(r=>r?.target)).size>1:!selected.length||(name==='伴随'&&new Set(selected.map(r=>r.target)).size!==1);}
function openContext(event:MouseEvent,row:Record<string,unknown>){const bounds=(event.currentTarget as HTMLElement)?.getBoundingClientRect();const x=Number.isFinite(event.clientX)?event.clientX:(bounds?.left||0)+30,y=Number.isFinite(event.clientY)?event.clientY:(bounds?.top||0)+30;context.value={x:Math.max(0,Math.min(x,window.innerWidth-190)),y:Math.max(0,Math.min(y,window.innerHeight-355)),row:row as unknown as Capture};}
async function action(name:string){if(disabled(name))return;const chosen=p.chosen.length?p.chosen as unknown as Capture[]:face.value&&context.value?[context.value.row]:[];context.value=null;if(name==='区域统计')p.formAnalysis('区域统计',undefined,rows.value);else if(name==='添加数据集')p.addDataset(rows.value);else await p.dataAction(name,chosen);}
function samePerson(row:Capture){if(apiMode==='http'){void guardedFace(async()=>{const record=p.remote.captures[row.id];if(record?.dataType!=='FACE'||!record.face.imageAssetId)throw new Error('当前采集记录没有可用图像');const blob=await downloadFileBinary(record.face.imageAssetId);const file=new File([blob],'reference.'+(blob.type==='image/png'?'png':'jpg'),{type:blob.type});const asset=await uploadControlled(file,'FACE_SEARCH',controller.signal);if(p.faceSource.startsWith('blob:'))URL.revokeObjectURL(p.faceSource);p.faceSource=URL.createObjectURL(blob);await startFaceSearch(asset.fileAssetId);});return;}const person=p.db.people.find(r=>r.id===row.person);p.faceSource=person?.image||'';p.faceReference=Number(row.person.replace(/\D/g,''));p.similarity=0;p.log('同人搜索');}
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;try{if(apiMode==='http'){feature('FACE_SEARCH');if(!candidateLimit.value)throw new Error('请先填写候选数量上限');controller.abort();controller=new AbortController();faceBusy.value=true;const asset=await uploadControlled(file,'FACE_SEARCH',controller.signal);if(p.faceSource.startsWith('blob:'))URL.revokeObjectURL(p.faceSource);p.faceSource=URL.createObjectURL(file);await startFaceSearch(asset.fileAssetId);return;}if(!['image/jpeg','image/png'].includes(file.type)||file.size>5*1024*1024)throw new Error('请上传不超过 5 MB 的 JPEG 或 PNG 图像');const bytes=new Uint8Array(await file.slice(0,8).arrayBuffer());if(!(bytes[0]===0xff&&bytes[1]===0xd8||bytes.slice(0,8).join(',')==='137,80,78,71,13,10,26,10'))throw new Error('图片内容与格式不匹配');const url=URL.createObjectURL(file);const img=new Image();img.src=url;try{await img.decode();}catch{URL.revokeObjectURL(url);throw new Error('图片无法解码');}if(p.faceSource.startsWith('blob:'))URL.revokeObjectURL(p.faceSource);p.faceSource=url;p.faceReference=0;p.similarity=0;p.log('上传照片搜图');}catch(e){faceError.value=e instanceof Error?e.message:String(e);ElMessage.error(faceError.value);}finally{faceBusy.value=false;(event.target as HTMLInputElement).value='';}}
function clearFace(){controller.abort();if(p.faceSource.startsWith('blob:'))URL.revokeObjectURL(p.faceSource);p.faceSource='';p.similarity=0;faceTask.value='';faceCursor.value=null;imageAssetId.value='';void p.query();}
function selectFace(checked:unknown,row:Capture){p.chosen=checked?[...p.chosen,row]:p.chosen.filter(r=>r.id!==row.id);}
async function savePhoto(row:Capture){if(apiMode==='http'){await guardedFace(async()=>{const record=p.remote.captures[row.id];if(record?.dataType!=='FACE'||!record.face.imageAssetId)throw new Error('当前记录没有图像文件');const asset=(await request('getFileAsset',{path:{fileAssetId:record.face.imageAssetId}})).data;if(asset.status!=='ACTIVE')throw new Error('图像文件不可用：'+asset.status);download(await downloadFileBinary(asset.fileAssetId),asset.fileName);});return;}const image=p.db.people.find(r=>r.id===row.person)?.image;if(image){const response=await fetch(image);download(await response.blob(),row.target+'.svg');p.log('保存人像图片');}}
function search(){p.chosen=[];if(apiMode==='http'&&face.value&&imageAssetId.value)void guardedFace(()=>startFaceSearch(imageAssetId.value));else void p.query();}
</script>
<template><div @click="context=null"><QueryForm :fields="fields" :model="p.f" @search="search" @reset="p.reset"><template v-if="face"><el-form-item v-if="apiMode==='http'" label="候选数量上限"><el-input-number v-model="candidateLimit" :min="1" aria-label="候选数量上限"/></el-form-item><label class="upload-button">上传照片<input type="file" accept="image/jpeg,image/png" @change="upload"/></label></template><el-button v-if="type==='电围'&&p.currentRole?.secret" @click="p.decryptForm()">密文解密</el-button></QueryForm><el-alert v-if="faceError" type="error" :title="faceError" :closable="false"/><el-alert v-if="faceBusy" type="info" title="人像任务处理中，可在任务中心查看进度" :closable="false"/><div class="query-split"><div class="stack"><template v-if="face"><section v-if="p.faceSource" class="card face-source"><h3>搜索原图</h3><img :src="p.faceSource" alt="搜索原图"/><label>相似度大于 {{p.similarity}}%<el-slider v-model="p.similarity" :min="0" :max="100"/></label><el-button @click="clearFace">清除搜图</el-button></section><section class="card"><div class="section-head"><h3>人像搜索结果</h3><span class="muted">{{rows.length}} 张</span></div><div class="face-gallery"><article v-for="row in rows" :key="row.id" class="face-card" tabindex="0" @contextmenu.prevent="openContext($event,row)" @keydown.shift.f10.prevent="openContext($event as unknown as MouseEvent,row)"><el-checkbox :model-value="p.chosen.some(r=>r.id===row.id)" :aria-label="'选择 '+row.target" @change="selectFace($event,row)"/><img v-if="images[row.id]||p.db.people.find(r=>r.id===row.person)?.image" :src="images[row.id]||p.db.people.find(r=>r.id===row.person)?.image" :alt="row.target"/><div v-else class="portrait-placeholder">人像待加载</div><div class="face-hover"><el-button size="small" @click="samePerson(row)">搜索</el-button><el-button size="small" @click="savePhoto(row)">保存</el-button></div><b>{{row.target}}</b><p>{{row.site}}</p><p class="muted">{{row.time}}</p><span v-if="p.faceSource" class="score">相似度 {{row.score}}%</span></article></div><el-empty v-if="!rows.length" description="当前条件下无结果"/><el-button v-if="apiMode==='http'&&faceCursor" @click="moreFaces">加载更多人像结果</el-button></section></template><DataTable v-else :rows="rows" :columns="columns" @select="p.chosen=$event" @open="row=>p.deviceInfo(String(row.deviceId))" @context="openContext"><template #actions><el-button @click="p.exportCaptures(rows)">导出</el-button><el-dropdown><el-button>目标操作</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-for="name in contextNames" :key="name" :disabled="disabled(name)" @click="action(name)">{{name}}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></DataTable><p class="hint">勾选数据后右键目标标识。未勾选时开放区域统计、添加数据集；也可使用“目标操作”按钮。</p></div><aside v-if="!face" class="card stats-panel"><h3>数据分析</h3><el-empty v-if="!p.statRows.length" description="勾选数据后，右键目标标识 → 统计" :image-size="80"/><template v-else><article v-for="row in p.statRows" :key="row.id"><el-checkbox-group v-model="p.statSelected"><el-checkbox :value="row.id">{{row.target}}</el-checkbox></el-checkbox-group><dl><dt>被采集总次数</dt><dd>{{row.count}}</dd><dt>经过站点数量</dt><dd>{{row.stations}}</dd><dt>经过区域数量</dt><dd>{{row.regions}}</dd><dt>最早出现时间</dt><dd>{{row.first}}</dd><dt>疑似落脚点</dt><dd>{{row.landing}}</dd></dl></article><div class="actions"><el-button v-for="name in ['检索','伴随','布控']" :key="name" :disabled="!p.statSelected.length||name==='伴随'&&p.statSelected.length!==1" @click="p.dataAction(name,p.statRows.filter(r=>p.statSelected.includes(r.id)).flatMap(r=>r.captures))">{{name}}</el-button></div></template></aside></div><Teleport to="body"><div v-if="context" class="context-backdrop" @click="context=null"/><div v-if="context" class="context-menu" role="menu" :style="{left:context.x+'px',top:context.y+'px'}"><button v-for="name in contextNames" :key="name" role="menuitem" :disabled="disabled(name)" @click.stop="action(name)">{{name}}</button></div></Teleport></div></template>



